/// MATRIX Connect — official Android companion app entry point.
///
/// Configure Firebase for this app with:
///   dart pub global activate flutterfire_cli
///   flutterfire configure --project=<matrix-firebase-project> --out=lib/firebase_options.dart
/// then run:
///   flutter run --dart-define=MATRIX_API_BASE=https://matrix.thamjj13.top
library;

import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'auth_gate.dart';
// Generated by `flutterfire configure` — see mobile/README.md.
import 'firebase_options.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  runApp(const MatrixApp());
}

class MatrixApp extends StatelessWidget {
  const MatrixApp({super.key});
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'MATRIX',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xFF3B82F6), brightness: Brightness.dark), useMaterial3: true),
      home: const AuthGate(),
    );
  }
}
